<file path="src/components/Footer.tsx">
import React from 'react';
import './Footer.css';

export function Footer() {
  const year = new Date().getFullYear();

  return (
    <footer className="ns-footer" id="footer" aria-label="Site Footer">
      <div className="ns-footer__inner">
        <div className="ns-footer__brand">
          <p className="ns-footer__logo">Neon Sound Festival</p>
          <p className="ns-footer__tagline">3 Nights of Immersive Electronic and Holographic Music</p>
        </div>

        <address className="ns-footer__contact">
          <h4 className="ns-footer__heading">Visit & Connect</h4>
          <p>Desert Oasis Grounds, Indio, CA 92201</p>
          <p><a href="tel:+1 (760) 555-0195">+1 (760) 555-0195</a></p>
          <p><a href="mailto:tickets@neonsoundfest.com">tickets@neonsoundfest.com</a></p>
        </address>

        <div className="ns-footer__hours">
          <h4 className="ns-footer__heading">Hours of Operation</h4>
          <p>Festival Dates: October 16–18, 2026 | Gates Open 2pm Daily</p>
        </div>
      </div>

      <div className="ns-footer__bottom">
        <p>&copy; {year} Neon Sound Festival. All rights reserved.</p>
      </div>
    </footer>
  );
}

</file>
<file path="src/components/Footer.css">
.ns-footer {
  background: rgb(6, 6, 8);
  border-top: 1px solid rgba(6, 182, 212, 0.14);
  padding: 4.5rem 2rem 2rem;
  color: #a1a1aa;
}

.ns-footer__inner {
  max-width: 1200px;
  margin: 0 auto;
  display: grid;
  grid-template-columns: 2fr 1.5fr 1.5fr;
  gap: 3rem;
  padding-bottom: 3rem;
  border-bottom: 1px solid rgba(255, 255, 255, 0.06);
}

.ns-footer__logo {
  font-family: 'Space Grotesk', sans-serif;
  font-size: 1.4rem;
  font-weight: 700;
  color: #fafafa;
  margin: 0 0 0.75rem;
}

.ns-footer__tagline {
  font-size: 0.95rem;
  line-height: 1.6;
  max-width: 320px;
  margin: 0;
}

.ns-footer__heading {
  font-size: 0.85rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  color: #06b6d4;
  margin: 0 0 1rem;
}

.ns-footer__contact,
.ns-footer__hours {
  font-style: normal;
  font-size: 0.92rem;
  line-height: 1.7;
}

.ns-footer__contact a {
  color: #fafafa;
  text-decoration: none;
  transition: color 0.2s ease;
}

.ns-footer__contact a:hover {
  color: #06b6d4;
}

.ns-footer__bottom {
  max-width: 1200px;
  margin: 2rem auto 0;
  text-align: center;
  font-size: 0.85rem;
  color: #71717a;
}

@media (max-width: 768px) {
  .ns-footer__inner {
    grid-template-columns: 1fr;
    gap: 2rem;
  }
}

@media (prefers-reduced-motion: reduce) {
  .ns-footer,
  .ns-footer__link {
    transition: none !important;
    transform: none !important;
  }
}

</file>
</tool_call>

