<tool_call name="write_site">
<file path="src/components/Header.tsx">
import React, { useState, useEffect } from 'react';
import './Header.css';

export function Header() {
  const [scrolled, setScrolled] = useState(false);
  const [menuOpen, setMenuOpen] = useState(false);

  useEffect(() => {
    const onScroll = () => setScrolled(window.scrollY > 15);
    window.addEventListener('scroll', onScroll, { passive: true });
    return () => window.removeEventListener('scroll', onScroll);
  }, []);

  return (
    <header className={`hir-header${scrolled ? ' hir-header--scrolled' : ''}`} role="banner">
      <div className="hir-header__inner">
        <a href="#" className="hir-header__logo" aria-label="Heavy Ink Risograph Home">
          Heavy Ink Risograph
        </a>

        <nav className="hir-header__nav" aria-label="Main Navigation">
          <a href="#hero" className="hir-header__link">Home</a>
          <a href="#print_formats" className="hir-header__link">Print Formats</a>
          <a href="#footer" className="hir-header__link">Contact</a>
        </nav>

        <div className="hir-header__actions">
          <a href="mailto:print@heavyink.co.uk" className="hir-header__cta">
            Order Print Run
          </a>
          <button
            type="button"
            className="hir-header__toggle"
            aria-label="Toggle navigation menu"
            aria-expanded={menuOpen}
            onClick={() => setMenuOpen(!menuOpen)}
          >
            <span className="hir-header__bar" />
            <span className="hir-header__bar" />
            <span className="hir-header__bar" />
          </button>
        </div>
      </div>

      {menuOpen && (
        <div className="hir-header__mobile-menu" role="dialog" aria-modal="true">
          <a href="#hero" className="hir-header__mobile-link" onClick={() => setMenuOpen(false)}>Home</a>
          <a href="#print_formats" className="hir-header__mobile-link" onClick={() => setMenuOpen(false)}>Print Formats</a>
          <a href="#footer" className="hir-header__mobile-link" onClick={() => setMenuOpen(false)}>Contact</a>
          <a href="mailto:print@heavyink.co.uk" className="hir-header__mobile-cta" onClick={() => setMenuOpen(false)}>Order Print Run</a>
        </div>
      )}
    </header>
  );
}
</file>
