import React, { useState, useEffect } from 'react';
import './Header.css';

export function Header() {
  const [scrolled, setScrolled] = useState(false);
  const [menuOpen, setMenuOpen] = useState(false);

  useEffect(() => {
    const onScroll = () => setScrolled(window.scrollY > 15);
    window.addEventListener('scroll', onScroll, { passive: true });
    return () => window.removeEventListener('scroll', onScroll);
  }, []);

  return (
    <header className={`vi-header${scrolled ? ' vi-header--scrolled' : ''}`} role="banner">
      <div className="vi-header__inner">
        <a href="#" className="vi-header__logo" aria-label="Vanguard Immuno-Oncology Home">
          Vanguard Immuno-Oncology
        </a>

        <nav className="vi-header__nav" aria-label="Main Navigation">
          <a href="#hero" className="vi-header__link">Home</a>
          <a href="#pillars" className="vi-header__link">Therapeutic Pillars</a>
          <a href="#footer" className="vi-header__link">Contact</a>
        </nav>

        <div className="vi-header__actions">
          <a href="mailto:intake@vanguardimmunooncology.org" className="vi-header__cta">
            Clinical Trials
          </a>
          <button
            type="button"
            className="vi-header__toggle"
            aria-label="Toggle navigation menu"
            aria-expanded={menuOpen}
            onClick={() => setMenuOpen(!menuOpen)}
          >
            <span className="vi-header__bar" />
            <span className="vi-header__bar" />
            <span className="vi-header__bar" />
          </button>
        </div>
      </div>

      {menuOpen && (
        <div className="vi-header__mobile-menu">
          <a href="#hero" onClick={() => setMenuOpen(false)}>Home</a>
          <a href="#pillars" onClick={() => setMenuOpen(false)}>Therapeutic Pillars</a>
          <a href="#footer" onClick={() => setMenuOpen(false)}>Contact</a>
        </div>
      )}
    </header>
  );
}

