import React, { useState, useEffect } from 'react';
import './Header.css';

export function Header() {
  const [scrolled, setScrolled] = useState(false);
  const [menuOpen, setMenuOpen] = useState(false);

  useEffect(() => {
    const onScroll = () => setScrolled(window.scrollY > 15);
    window.addEventListener('scroll', onScroll, { passive: true });
    return () => window.removeEventListener('scroll', onScroll);
  }, []);

  return (
    <header className={`ce-header${scrolled ? ' ce-header--scrolled' : ''}`} role="banner">
      <div className="ce-header__inner">
        <a href="#" className="ce-header__logo" aria-label="Clarity Eye Studio Home">
          Clarity Eye Studio
        </a>

        <nav className="ce-header__nav" aria-label="Main Navigation">
          <a href="#hero" className="ce-header__link">Home</a>
          <a href="#collections" className="ce-header__link">Eyewear Collections</a>
          <a href="#footer" className="ce-header__link">Contact</a>
        </nav>

        <div className="ce-header__actions">
          <a href="mailto:care@clarityeyestudio.com" className="ce-header__cta">
            Book Eye Exam
          </a>
          <button
            type="button"
            className="ce-header__toggle"
            aria-label="Toggle navigation menu"
            aria-expanded={menuOpen}
            onClick={() => setMenuOpen(!menuOpen)}
          >
            <span className="ce-header__bar" />
            <span className="ce-header__bar" />
            <span className="ce-header__bar" />
          </button>
        </div>
      </div>

      {menuOpen && (
        <div className="ce-header__mobile-menu">
          <a href="#hero" onClick={() => setMenuOpen(false)}>Home</a>
          <a href="#collections" onClick={() => setMenuOpen(false)}>Eyewear Collections</a>
          <a href="#footer" onClick={() => setMenuOpen(false)}>Contact</a>
        </div>
      )}
    </header>
  );
