import React, { useState, useEffect } from 'react';
import './Header.css';

export function Header() {
  const [scrolled, setScrolled] = useState(false);
  const [menuOpen, setMenuOpen] = useState(false);

  useEffect(() => {
    const onScroll = () => setScrolled(window.scrollY > 15);
    window.addEventListener('scroll', onScroll, { passive: true });
    return () => window.removeEventListener('scroll', onScroll);
  }, []);

  return (
    <header className={`hw-header${scrolled ? ' hw-header--scrolled' : ''}`} role="banner">
      <div className="hw-header__inner">
        <a href="#" className="hw-header__logo" aria-label="Harmony Workspace Home">
          Harmony Workspace
        </a>

        <nav className="hw-header__nav" aria-label="Main Navigation">
          <a href="#hero" className="hw-header__link">Home</a>
          <a href="#workspace_modules" className="hw-header__link">Workspace Modules</a>
          <a href="#footer" className="hw-header__link">Contact</a>
        </nav>

        <div className="hw-header__actions">
          <a href="mailto:teams@harmonyworkspace.com" className="hw-header__cta">
            Create Free Team Space
          </a>
          <button
            type="button"
            className="hw-header__toggle"
            aria-label="Toggle navigation menu"
            aria-expanded={menuOpen}
            onClick={() => setMenuOpen(!menuOpen)}
          >
            <span className="hw-header__bar" />
            <span className="hw-header__bar" />
            <span className="hw-header__bar" />
          </button>
        </div>
      </div>

      {menuOpen && (
        <div className="hw-header__mobile-menu" role="dialog" aria-modal="true">
          <a href="#hero" className="hw-header__mobile-link" onClick={() => setMenuOpen(false)}>Home</a>
          <a href="#workspace_modules" className="hw-header__mobile-link" onClick={() => setMenuOpen(false)}>Workspace Modules</a>
          <a href="#footer" className="hw-header__mobile-link" onClick={() => setMenuOpen(false)}>Contact</a>
          <a href="mailto:teams@harmonyworkspace.com" className="hw-header__mobile-cta" onClick={() => setMenuOpen(false)}>Create Free Team Space</a>
        </div>
      )}
    </header>
  );
}
