import React, { useState, useEffect } from 'react';
import './Header.css';

export function Header() {
  const [scrolled, setScrolled] = useState(false);
  const [menuOpen, setMenuOpen] = useState(false);

  useEffect(() => {
    const onScroll = () => setScrolled(window.scrollY > 15);
    window.addEventListener('scroll', onScroll, { passive: true });
    return () => window.removeEventListener('scroll', onScroll);
  }, []);

  return (
    <header className={`sko-header${scrolled ? ' sko-header--scrolled' : ''}`} role="banner">
      <div className="sko-header__inner">
        <a href="#" className="sko-header__logo" aria-label="Strata Kernel Observability Home">
          Strata Kernel Observability
        </a>

        <nav className="sko-header__nav" aria-label="Main Navigation">
          <a href="#hero" className="sko-header__link">Home</a>
          <a href="#stack_modules" className="sko-header__link">Observability Stack</a>
          <a href="#footer" className="sko-header__link">Contact</a>
        </nav>

        <div className="sko-header__actions">
          <a href="mailto:telemetry@strataobservability.com" className="sko-header__cta">
            Connect Kubernetes Cluster
          </a>
          <button
            type="button"
            className="sko-header__toggle"
            aria-label="Toggle navigation menu"
            aria-expanded={menuOpen}
            onClick={() => setMenuOpen(!menuOpen)}
          >
            <span className="sko-header__bar" />
            <span className="sko-header__bar" />
            <span className="sko-header__bar" />
          </button>
        </div>
      </div>

      {menuOpen && (
        <div className="sko-header__mobile-menu" role="dialog" aria-modal="true">
          <a href="#hero" className="sko-header__mobile-link" onClick={() => setMenuOpen(false)}>Home</a>
          <a href="#stack_modules" className="sko-header__mobile-link" onClick={() => setMenuOpen(false)}>Observability Stack</a>
          <a href="#footer" className="sko-header__mobile-link" onClick={() => setMenuOpen(false)}>Contact</a>
          <a href="mailto:telemetry@strataobservability.com" className="sko-header__mobile-cta" onClick={() => setMenuOpen(false)}>Connect Kubernetes Cluster</a>
        </div>
      )}
    </header>
  );
}
