          <a href="#schedule" className="ds-header__link">Schedule</a>
          <a href="#footer" className="ds-header__link">Contact</a>
        </nav>
        <a href="mailto:tickets@devsummit.io" className="ds-header__cta">Get Tickets</a>
      </div>
    </header>
  );
}
