import React, { useState, useEffect } from 'react';
import './Header.css';

export function Header() {
  const [scrolled, setScrolled] = useState(false);
  const [menuOpen, setMenuOpen] = useState(false);

  useEffect(() => {
    const onScroll = () => setScrolled(window.scrollY > 15);
    window.addEventListener('scroll', onScroll, { passive: true });
    return () => window.removeEventListener('scroll', onScroll);
  }, []);

  return (
    <header className={`thq-header${scrolled ? ' thq-header--scrolled' : ''}`} role="banner">
      <div className="thq-header__inner">
        <a href="#" className="thq-header__logo" aria-label="ToggleHQ Control Home">
          ToggleHQ Control
        </a>

        <nav className="thq-header__nav" aria-label="Main Navigation">
          <a href="#hero" className="thq-header__link">Home</a>
          <a href="#release_controls" className="thq-header__link">Release Controls</a>
          <a href="#footer" className="thq-header__link">Contact</a>
        </nav>

        <div className="thq-header__actions">
          <a href="mailto:support@togglehq.dev" className="thq-header__cta">
            Create Free Flag
          </a>
          <button
            type="button"
            className="thq-header__toggle"
            aria-label="Toggle navigation menu"
            aria-expanded={menuOpen}
            onClick={() => setMenuOpen(!menuOpen)}
          >
            <span className="thq-header__bar" />
            <span className="thq-header__bar" />
            <span className="thq-header__bar" />
          </button>
        </div>
      </div>

      {menuOpen && (
        <div className="thq-header__mobile-menu" role="dialog" aria-modal="true">
          <a href="#hero" className="thq-header__mobile-link" onClick={() => setMenuOpen(false)}>Home</a>
          <a href="#release_controls" className="thq-header__mobile-link" onClick={() => setMenuOpen(false)}>Release Controls</a>
          <a href="#footer" className="thq-header__mobile-link" onClick={() => setMenuOpen(false)}>Contact</a>
          <a href="mailto:support@togglehq.dev" className="thq-header__mobile-cta" onClick={() => setMenuOpen(false)}>Create Free Flag</a>
        </div>
      )}
    </header>
  );
}
