import React, { useState, useEffect } from 'react';
import './Header.css';

export function Header() {
  const [scrolled, setScrolled] = useState(false);
  const [menuOpen, setMenuOpen] = useState(false);

  useEffect(() => {
    const onScroll = () => setScrolled(window.scrollY > 15);
    window.addEventListener('scroll', onScroll, { passive: true });
    return () => window.removeEventListener('scroll', onScroll);
  }, []);

  return (
    <header className={`ad-header${scrolled ? ' ad-header--scrolled' : ''}`} role="banner">
      <div className="ad-header__inner">
        <a href="#" className="ad-header__logo" aria-label="Aura Dermatology & Laser Home">
          Aura Dermatology & Laser
        </a>

        <nav className="ad-header__nav" aria-label="Main Navigation">
          <a href="#hero" className="ad-header__link">Home</a>
          <a href="#treatments" className="ad-header__link">Clinical Treatments</a>
          <a href="#footer" className="ad-header__link">Contact</a>
        </nav>

        <div className="ad-header__actions">
          <a href="mailto:concierge@auraderm.com" className="ad-header__cta">
            Consult Specialist
          </a>
          <button
            type="button"
            className="ad-header__toggle"
            aria-label="Toggle navigation menu"
            aria-expanded={menuOpen}
            onClick={() => setMenuOpen(!menuOpen)}
          >
            <span className="ad-header__bar" />
            <span className="ad-header__bar" />
            <span className="ad-header__bar" />
          </button>
        </div>
      </div>

      {menuOpen && (
        <div className="ad-header__mobile-menu">
          <a href="#hero" onClick={() => setMenuOpen(false)}>Home</a>
