import React, { useState, useEffect } from 'react';
import './Header.css';

export function Header() {
  const [scrolled, setScrolled] = useState(false);
  const [menuOpen, setMenuOpen] = useState(false);

  useEffect(() => {
    const onScroll = () => setScrolled(window.scrollY > 15);
    window.addEventListener('scroll', onScroll, { passive: true });
    return () => window.removeEventListener('scroll', onScroll);
  }, []);

  return (
    <header className={`sot-header${scrolled ? ' sot-header--scrolled' : ''}`} role="banner">
      <div className="sot-header__inner">
        <a href="#" className="sot-header__logo" aria-label="Stellar Orbit Telemetry Home">
          Stellar Orbit Telemetry
        </a>

        <nav className="sot-header__nav" aria-label="Main Navigation">
          <a href="#hero" className="sot-header__link">Home</a>
          <a href="#mission_modules" className="sot-header__link">Mission Control Modules</a>
          <a href="#footer" className="sot-header__link">Contact</a>
        </nav>

        <div className="sot-header__actions">
          <a href="mailto:missionops@stellarorbit.space" className="sot-header__cta">
            Schedule Mission Demo
          </a>
          <button
            type="button"
            className="sot-header__toggle"
            aria-label="Toggle navigation menu"
            aria-expanded={menuOpen}
            onClick={() => setMenuOpen(!menuOpen)}
          >
            <span className="sot-header__bar" />
            <span className="sot-header__bar" />
            <span className="sot-header__bar" />
          </button>
        </div>
      </div>

      {menuOpen && (
        <div className="sot-header__mobile-menu" role="dialog" aria-modal="true">
          <a href="#hero" className="sot-header__mobile-link" onClick={() => setMenuOpen(false)}>Home</a>
          <a href="#mission_modules" className="sot-header__mobile-link" onClick={() => setMenuOpen(false)}>Mission Control Modules</a>
          <a href="#footer" className="sot-header__mobile-link" onClick={() => setMenuOpen(false)}>Contact</a>
          <a href="mailto:missionops@stellarorbit.space" className="sot-header__mobile-cta" onClick={() => setMenuOpen(false)}>Schedule Mission Demo</a>
        </div>
      )}
    </header>
  );
}
