import React, { useState, useEffect } from 'react';
import './Header.css';

export function Header() {
  const [scrolled, setScrolled] = useState(false);
  const [menuOpen, setMenuOpen] = useState(false);

  useEffect(() => {
    const onScroll = () => setScrolled(window.scrollY > 15);
    window.addEventListener('scroll', onScroll, { passive: true });
    return () => window.removeEventListener('scroll', onScroll);
  }, []);

  return (
    <header className={`ppm-header${scrolled ? ' ppm-header--scrolled' : ''}`} role="banner">
      <div className="ppm-header__inner">
        <a href="#" className="ppm-header__logo" aria-label="PingPulse Monitoring Home">
          PingPulse Monitoring
        </a>

        <nav className="ppm-header__nav" aria-label="Main Navigation">
          <a href="#hero" className="ppm-header__link">Home</a>
          <a href="#monitoring" className="ppm-header__link">Monitoring Tools</a>
          <a href="#footer" className="ppm-header__link">Contact</a>
        </nav>

        <div className="ppm-header__actions">
          <a href="mailto:ops@pingpulse.io" className="ppm-header__cta">
            Add Free Website Monitor
          </a>
          <button
            type="button"
            className="ppm-header__toggle"
            aria-label="Toggle navigation menu"
            aria-expanded={menuOpen}
            onClick={() => setMenuOpen(!menuOpen)}
          >
            <span className="ppm-header__bar" />
            <span className="ppm-header__bar" />
            <span className="ppm-header__bar" />
          </button>
        </div>
      </div>

      {menuOpen && (
        <div className="ppm-header__mobile-menu" role="dialog" aria-modal="true">
          <a href="#hero" className="ppm-header__mobile-link" onClick={() => setMenuOpen(false)}>Home</a>
