import React, { useState, useEffect } from 'react';
import './Header.css';

export function Header() {
  const [scrolled, setScrolled] = useState(false);
  const [menuOpen, setMenuOpen] = useState(false);

  useEffect(() => {
    const onScroll = () => setScrolled(window.scrollY > 15);
    window.addEventListener('scroll', onScroll, { passive: true });
    return () => window.removeEventListener('scroll', onScroll);
  }, []);

  return (
    <header className={`ro-header${scrolled ? ' ro-header--scrolled' : ''}`} role="banner">
      <div className="ro-header__inner">
        <a href="#" className="ro-header__logo" aria-label="Ronin Martial Arts Academy Home">
          Ronin Martial Arts Academy
        </a>

        <nav className="ro-header__nav" aria-label="Main Navigation">
          <a href="#hero" className="ro-header__link">Home</a>
          <a href="#programs" className="ro-header__link">Academy Programs</a>
          <a href="#footer" className="ro-header__link">Contact</a>
        </nav>

        <div className="ro-header__actions">
          <a href="mailto:oss@roninbjjacademy.com" className="ro-header__cta">
            Claim Free Trial Class
          </a>
          <button
            type="button"
            className="ro-header__toggle"
            aria-label="Toggle navigation menu"
            aria-expanded={menuOpen}
            onClick={() => setMenuOpen(!menuOpen)}
          >
            <span className="ro-header__bar" />
            <span className="ro-header__bar" />
            <span className="ro-header__bar" />
          </button>
        </div>
      </div>

      {menuOpen && (
        <div className="ro-header__mobile-menu">
          <a href="#hero" onClick={() => setMenuOpen(false)}>Home</a>
          <a href="#programs" onClick={() => setMenuOpen(false)}>Academy Programs</a>
          <a href="#footer" onClick={() => setMenuOpen(false)}>Contact</a>
        </div>
      )}
    </header>
  );
}

