import React, { useState } from 'react';
import './ReleaseControls.css';

interface Feature {
  id: string;
  category: string;
  title: string;
  desc: string;
  badge: string;
}

interface Review {
  id: string;
  quote: string;
  author: string;
  role: string;
  rating: number;
}

const FEATURES: Feature[] = [{'title': 'Sub-Millisecond Local Flag Eval', 'tag': 'Streaming Sync', 'desc': 'Flags evaluate in-memory in your application runtime with streaming updates over server-sent events.'}, {'title': 'Targeted User Segmentation', 'tag': 'Attribute Based', 'desc': 'Target features based on email domain, subscription tier, beta opt-in, or geographical location.'}, {'title': 'Automatic Metric Circuit Breaker', 'tag': 'Crash Protection', 'desc': 'Automatically turn off a new feature flag if application crash rates spike by more than 0.2%.'}, {'title': 'Audit Logs & Approval Workflows', 'tag': 'Dual-Approval', 'desc': 'Require peer review and manager sign-off before toggling critical infrastructure flags in production.'}];
const REVIEWS: Review[] = [{'id': '1', 'quote': 'Deploying ToggleHQ Control transformed our delivery velocity. The sub-millisecond local flag eval capabilities delivered immediate impact.', 'author': 'Alex Chen', 'role': 'Head of Engineering, ToggleHQ Control', 'rating': 5}, {'id': '2', 'quote': 'With ToggleHQ Control, we automated real-time feature flagging, canary releases & instant kill-switches while accelerating our product delivery.', 'author': 'Samantha Wei', 'role': 'VP of Technology at ToggleHQ Control Group', 'rating': 5}, {'id': '3', 'quote': 'Our developers love using ToggleHQ Control. The targeted user segmentation workflow is best in class.', 'author': 'Marcus Thorne', 'role': 'Principal Architect', 'rating': 5}];
const CATEGORIES: { id: string; label: string }[] = [{'id': 'all', 'label': 'All Capabilities'}, {'id': 'core', 'label': 'Core Engine'}, {'id': 'security', 'label': 'Security & Auth'}, {'id': 'scale', 'label': 'Scale & Telemetry'}];

export function ReleaseControls() {
  const [activeTab, setActiveTab] = useState<string>('all');
  const [activeSlide, setActiveSlide] = useState<number>(0);

  const filteredFeatures = activeTab === 'all'
    ? FEATURES
    : FEATURES.filter((f) => f.category === activeTab);

  const prevSlide = () => {
    setActiveSlide((prev) => (prev - 1 + REVIEWS.length) % REVIEWS.length);
  };

  const nextSlide = () => {
    setActiveSlide((prev) => (prev + 1) % REVIEWS.length);
  };

  const currentReview = REVIEWS[activeSlide];

  return (
    <section className="thq-tabs" id="releasecontrols" aria-labelledby="thq-tabs-title">
      <div className="thq-tabs__inner">
        {/* 1. Header & Tab Navigation */}
        <div className="thq-tabs__header">
          <p className="thq-tabs__eyebrow">DEVOPS SOLUTIONS</p>
          <h2 id="thq-tabs-title" className="thq-tabs__title">
            Release Controls
          </h2>
          <p className="thq-tabs__subtitle">
            Explore verified solutions and live client outcomes from ToggleHQ Control.
          </p>

          <div className="thq-tabs__nav" role="tablist" aria-label="Feature categories">
            {CATEGORIES.map((cat) => (
              <button
                key={cat.id}
                type="button"
                role="tab"
                aria-selected={activeTab === cat.id}
                className={`thq-tabs__tab${activeTab === cat.id ? ' is-active' : ''}`}
                onClick={() => setActiveTab(cat.id)}
              >
                {cat.label}
              </button>
            ))}
          </div>
        </div>

        {/* 2. Filtered Cards Grid */}
        <div className="thq-tabs__grid">
          {filteredFeatures.map((item) => (
            <div key={item.id} className="thq-tabs__card">
              <div className="thq-tabs__card-top">
                <span className="thq-tabs__badge">{item.badge}</span>
                <span className="thq-tabs__category">{item.category}</span>
              </div>
              <h3 className="thq-tabs__card-title">{item.title}</h3>
              <p className="thq-tabs__card-desc">{item.desc}</p>
            </div>
          ))}
        </div>

        {/* 3. Carousel Component — Testimonials & Proof */}
        <div className="thq-tabs__carousel" aria-label="Customer Testimonials">
          <div className="thq-tabs__carousel-box">
            <div className="thq-tabs__stars" aria-label="5 stars rating">
              {'★'.repeat(currentReview.rating)}
            </div>

            <blockquote className="thq-tabs__quote">
              &ldquo;{currentReview.quote}&rdquo;
            </blockquote>

            <div className="thq-tabs__author">
              <div className="thq-tabs__author-avatar" aria-hidden="true">
                {currentReview.author.split(' ').map((n) => n[0]).join('')}
              </div>
              <div>
                <h4 className="thq-tabs__author-name">{currentReview.author}</h4>
                <span className="thq-tabs__author-role">{currentReview.role}</span>
              </div>
            </div>

            <div className="thq-tabs__carousel-controls">
              <button
                type="button"
                onClick={prevSlide}
                className="thq-tabs__carousel-btn"
                aria-label="Previous testimonial"
              >
                &larr;
              </button>
              <span className="thq-tabs__carousel-counter">
                0{activeSlide + 1} / 0{REVIEWS.length}
              </span>
              <button
                type="button"
                onClick={nextSlide}
                className="thq-tabs__carousel-btn"
                aria-label="Next testimonial"
              >
                &rarr;
              </button>
            </div>
          </div>
        </div>
      </div>
    </section>
  );
}
