import React from 'react';
import './VoyageHighlights.css';

interface Milestone {
  step: string;
  title: string;
  tag: string;
  desc: string;
}

const MILESTONES: Milestone[] = [
  {
    "step": "Phase 01",
    "title": "Imperial Suite Carriage",
    "tag": "Private Ensuite",
    "desc": "Spacious double bedroom with brass bedstead, private hot shower, writing desk, and dedicated 24-hour steward."
  },
  {
    "step": "Phase 02",
    "title": "Fine Dining Car 'Samarkand'",
    "tag": "Culinary Journey",
    "desc": "White linen silver service serving regional saffron lamb plov, Caspian caviar, and Georgian vintage wines."
  },
  {
    "step": "Phase 03",
    "title": "Observation Lounge & Bar",
    "tag": "Pianist & Cocktails",
    "desc": "Panoramic bay windows with nightly live classical piano performances as desert dunes sweep past."
  },
  {
    "step": "Phase 04",
    "title": "Private Architectural Excursions",
    "tag": "Historian Led",
    "desc": "Skip-the-line guided visits to turquoise tiled madrasas, ancient desert fortresses, and spice bazaars."
  }
];

export function VoyageHighlights() {
  const trackRef = React.useRef<HTMLDivElement>(null);

  React.useEffect(() => {
    const observer = new IntersectionObserver(
      (entries) => {
        entries.forEach((entry) => {
          if (entry.isIntersecting) {
            entry.target.classList.add('is-revealed');
          }
        });
      },
      { threshold: 0.2 }
    );

    const nodes = trackRef.current?.querySelectorAll('.sr-timeline__node');
    nodes?.forEach((node) => observer.observe(node));

    return () => observer.disconnect();
  }, []);

  return (
    <section className="sr-timeline" id="voyages" aria-labelledby="sr-timeline-title">
      <div className="sr-timeline__inner">
        <div className="sr-timeline__header">
          <p className="sr-timeline__eyebrow">Sequential Roadmap</p>
          <h2 id="sr-timeline-title" className="sr-timeline__title">
            Voyage Highlights
          </h2>
          <p className="sr-timeline__desc">
            Luxury transcontinental train journeys across ancient trade routes with private en-suite sleeper cars and fine dining.
          </p>
        </div>

        <div ref={trackRef} className="sr-timeline__track">
          <div className="sr-timeline__spine" aria-hidden="true" />
          {MILESTONES.map((m) => (
            <article key={m.title} className="sr-timeline__node">
              <div className="sr-timeline__marker" aria-hidden="true">
                <span className="sr-timeline__dot" />
              </div>
              <div className="sr-timeline__card">
                <div className="sr-timeline__card-top">
                  <span className="sr-timeline__step">{m.step}</span>
                  <span className="sr-timeline__tag">{m.tag}</span>
                </div>
                <h3 className="sr-timeline__card-title">{m.title}</h3>
                <p className="sr-timeline__card-desc">{m.desc}</p>
              </div>
            </article>
          ))}
        </div>
      </div>
    </section>
  );
}

