          <a href="#garments" className="srb-header__link">Bespoke Garments</a>
          <a href="#footer" className="srb-header__link">Contact</a>
        </nav>

        <div className="srb-header__actions">
          <a href="mailto:tailoring@savileandrow.com" className="srb-header__cta">
            Book Initial Fitting
          </a>
          <button
            type="button"
            className="srb-header__toggle"
            aria-label="Toggle navigation menu"
            aria-expanded={menuOpen}
            onClick={() => setMenuOpen(!menuOpen)}
          >
            <span className="srb-header__bar" />
            <span className="srb-header__bar" />
            <span className="srb-header__bar" />
          </button>
        </div>
      </div>

      {menuOpen && (
        <div className="srb-header__mobile-menu" role="dialog" aria-modal="true">
