import React, { useState, useEffect } from 'react';
import './Header.css';

export function Header() {
  const [scrolled, setScrolled] = useState(false);
  const [menuOpen, setMenuOpen] = useState(false);

  useEffect(() => {
    const onScroll = () => setScrolled(window.scrollY > 15);
    window.addEventListener('scroll', onScroll, { passive: true });
    return () => window.removeEventListener('scroll', onScroll);
  }, []);

  return (
    <header className={`imk-header${scrolled ? ' imk-header--scrolled' : ''}`} role="banner">
      <div className="imk-header__inner">
        <a href="#" className="imk-header__logo" aria-label="Ironclad Mechanical Keys Home">
          Ironclad Mechanical Keys
        </a>

        <nav className="imk-header__nav" aria-label="Main Navigation">
          <a href="#hero" className="imk-header__link">Home</a>
          <a href="#keyboards" className="imk-header__link">Keyboard Boards</a>
          <a href="#footer" className="imk-header__link">Contact</a>
        </nav>

        <div className="imk-header__actions">
          <a href="mailto:builds@ironcladkeys.com" className="imk-header__cta">
            Join Group Buy
          </a>
          <button
            type="button"
            className="imk-header__toggle"
            aria-label="Toggle navigation menu"
            aria-expanded={menuOpen}
            onClick={() => setMenuOpen(!menuOpen)}
          >
            <span className="imk-header__bar" />
            <span className="imk-header__bar" />
            <span className="imk-header__bar" />
          </button>
        </div>
      </div>

      {menuOpen && (
        <div className="imk-header__mobile-menu" role="dialog" aria-modal="true">
          <a href="#hero" className="imk-header__mobile-link" onClick={() => setMenuOpen(false)}>Home</a>
          <a href="#keyboards" className="imk-header__mobile-link" onClick={() => setMenuOpen(false)}>Keyboard Boards</a>
          <a href="#footer" className="imk-header__mobile-link" onClick={() => setMenuOpen(false)}>Contact</a>
          <a href="mailto:builds@ironcladkeys.com" className="imk-header__mobile-cta" onClick={() => setMenuOpen(false)}>Join Group Buy</a>
        </div>
      )}
    </header>
  );
}
