        <div className="ls-header__actions">
          <a href="mailto:admissions@littlestepstherapy.org" className="ls-header__cta">
            Request Evaluation
          </a>
          <button
            type="button"
            className="ls-header__toggle"
            aria-label="Toggle navigation menu"
            aria-expanded={menuOpen}
            onClick={() => setMenuOpen(!menuOpen)}
          >
            <span className="ls-header__bar" />
            <span className="ls-header__bar" />
            <span className="ls-header__bar" />
          </button>
        </div>
      </div>

      {menuOpen && (
