import React, { useState, useEffect } from 'react';
import './Header.css';

export function Header() {
  const [scrolled, setScrolled] = useState(false);
  const [menuOpen, setMenuOpen] = useState(false);

  useEffect(() => {
    const onScroll = () => setScrolled(window.scrollY > 15);
    window.addEventListener('scroll', onScroll, { passive: true });
    return () => window.removeEventListener('scroll', onScroll);
  }, []);

  return (
    <header className={`hfh-header${scrolled ? ' hfh-header--scrolled' : ''}`} role="banner">
      <div className="hfh-header__inner">
        <a href="#" className="hfh-header__logo" aria-label="Hackers & Founders Home">
          Hackers & Founders
        </a>

        <nav className="hfh-header__nav" aria-label="Main Navigation">
          <a href="#hero" className="hfh-header__link">Home</a>
          <a href="#criteria" className="hfh-header__link">Grant Criteria</a>
          <a href="#footer" className="hfh-header__link">Contact</a>
        </nav>

        <div className="hfh-header__actions">
          <a href="mailto:grants@hackersfounders.co" className="hfh-header__cta">
            Submit Your Project
          </a>
          <button
            type="button"
            className="hfh-header__toggle"
            aria-label="Toggle navigation menu"
            aria-expanded={menuOpen}
            onClick={() => setMenuOpen(!menuOpen)}
          >
            <span className="hfh-header__bar" />
            <span className="hfh-header__bar" />
            <span className="hfh-header__bar" />
          </button>
        </div>
      </div>

      {menuOpen && (
        <div className="hfh-header__mobile-menu" role="dialog" aria-modal="true">
          <a href="#hero" className="hfh-header__mobile-link" onClick={() => setMenuOpen(false)}>Home</a>
          <a href="#criteria" className="hfh-header__mobile-link" onClick={() => setMenuOpen(false)}>Grant Criteria</a>
          <a href="#footer" className="hfh-header__mobile-link" onClick={() => setMenuOpen(false)}>Contact</a>
          <a href="mailto:grants@hackersfounders.co" className="hfh-header__mobile-cta" onClick={() => setMenuOpen(false)}>Submit Your Project</a>
        </div>
      )}
    </header>
  );
}
