import React, { useState, useEffect } from 'react';
import './Header.css';

export function Header() {
  const [scrolled, setScrolled] = useState(false);
  const [menuOpen, setMenuOpen] = useState(false);

  useEffect(() => {
    const onScroll = () => setScrolled(window.scrollY > 15);
    window.addEventListener('scroll', onScroll, { passive: true });
    return () => window.removeEventListener('scroll', onScroll);
  }, []);

  return (
    <header className={`sny-header${scrolled ? ' sny-header--scrolled' : ''}`} role="banner">
      <div className="sny-header__inner">
        <a href="#" className="sny-header__logo" aria-label="Sovereign Naval Yachts Home">
          Sovereign Naval Yachts
        </a>

        <nav className="sny-header__nav" aria-label="Main Navigation">
          <a href="#hero" className="sny-header__link">Home</a>
          <a href="#yachts" className="sny-header__link">Yacht Concepts</a>
          <a href="#footer" className="sny-header__link">Contact</a>
        </nav>

        <div className="sny-header__actions">
          <a href="mailto:naval@sovereignyachts.mc" className="sny-header__cta">
            Request Commission Brief
          </a>
          <button
            type="button"
            className="sny-header__toggle"
            aria-label="Toggle navigation menu"
            aria-expanded={menuOpen}
            onClick={() => setMenuOpen(!menuOpen)}
          >
            <span className="sny-header__bar" />
            <span className="sny-header__bar" />
            <span className="sny-header__bar" />
          </button>
        </div>
      </div>

      {menuOpen && (
        <div className="sny-header__mobile-menu" role="dialog" aria-modal="true">
          <a href="#hero" className="sny-header__mobile-link" onClick={() => setMenuOpen(false)}>Home</a>
          <a href="#yachts" className="sny-header__mobile-link" onClick={() => setMenuOpen(false)}>Yacht Concepts</a>
