import React from 'react';
import './Checkbox.css';

export interface CheckboxProps {
  checked: boolean;
  onCheckedChange: (checked: boolean) => void;
  id?: string;
  label?: string;
  disabled?: boolean;
  className?: string;
}

export function Checkbox({
  checked,
  onCheckedChange,
  id,
  label,
  disabled = false,
  className = ''
}: CheckboxProps) {
  return (
    <div className={`shadcn-checkbox-wrap ${className}`.trim()}>
      <button
        type="button"
        role="checkbox"
        id={id}
        aria-checked={checked}
        disabled={disabled}
        onClick={() => !disabled && onCheckedChange(!checked)}
        className={`shadcn-checkbox ${checked ? 'checked' : ''}`}
      >
        {checked && <span className="shadcn-checkbox__check">✓</span>}
      </button>
      {label && <label htmlFor={id} className="shadcn-checkbox__label">{label}</label>}
    </div>
  );
}
