import React, { useState, useEffect } from 'react';
import './Header.css';

export function Header() {
  const [scrolled, setScrolled] = useState(false);
  const [menuOpen, setMenuOpen] = useState(false);

  useEffect(() => {
    const onScroll = () => setScrolled(window.scrollY > 15);
    window.addEventListener('scroll', onScroll, { passive: true });
    return () => window.removeEventListener('scroll', onScroll);
  }, []);

  return (
    <header className={`afo-header${scrolled ? ' afo-header--scrolled' : ''}`} role="banner">
      <div className="afo-header__inner">
        <a href="#" className="afo-header__logo" aria-label="Aurum Family Office Home">
          Aurum Family Office
        </a>

        <nav className="afo-header__nav" aria-label="Main Navigation">
          <a href="#hero" className="afo-header__link">Home</a>
          <a href="#wealth_practices" className="afo-header__link">Fiduciary Practices</a>
          <a href="#footer" className="afo-header__link">Contact</a>
        </nav>

        <div className="afo-header__actions">
          <a href="mailto:partners@aurumfamilyoffice.ch" className="afo-header__cta">
            Private Client Inquiry
          </a>
          <button
            type="button"
            className="afo-header__toggle"
            aria-label="Toggle navigation menu"
            aria-expanded={menuOpen}
            onClick={() => setMenuOpen(!menuOpen)}
          >
            <span className="afo-header__bar" />
            <span className="afo-header__bar" />
            <span className="afo-header__bar" />
          </button>
        </div>
      </div>

      {menuOpen && (
        <div className="afo-header__mobile-menu" role="dialog" aria-modal="true">
          <a href="#hero" className="afo-header__mobile-link" onClick={() => setMenuOpen(false)}>Home</a>
          <a href="#wealth_practices" className="afo-header__mobile-link" onClick={() => setMenuOpen(false)}>Fiduciary Practices</a>
          <a href="#footer" className="afo-header__mobile-link" onClick={() => setMenuOpen(false)}>Contact</a>
          <a href="mailto:partners@aurumfamilyoffice.ch" className="afo-header__mobile-cta" onClick={() => setMenuOpen(false)}>Private Client Inquiry</a>
        </div>
      )}
    </header>
  );
}
