import React, { useState, useEffect } from 'react';
import './Header.css';

export function Header() {
  const [scrolled, setScrolled] = useState(false);
  const [menuOpen, setMenuOpen] = useState(false);

  useEffect(() => {
    const onScroll = () => setScrolled(window.scrollY > 15);
    window.addEventListener('scroll', onScroll, { passive: true });
    return () => window.removeEventListener('scroll', onScroll);
  }, []);

  return (
    <header className={`spa-header${scrolled ? ' spa-header--scrolled' : ''}`} role="banner">
      <div className="spa-header__inner">
        <a href="#" className="spa-header__logo" aria-label="Sovereign Private Aviation Home">
          Sovereign Private Aviation
        </a>

        <nav className="spa-header__nav" aria-label="Main Navigation">
          <a href="#hero" className="spa-header__link">Home</a>
          <a href="#fleet" className="spa-header__link">Fleet Specifications</a>
          <a href="#footer" className="spa-header__link">Contact</a>
        </nav>

        <div className="spa-header__actions">
          <a href="mailto:charter@sovereignaviation.com" className="spa-header__cta">
            Book Private Flight
          </a>
          <button
            type="button"
            className="spa-header__toggle"
            aria-label="Toggle navigation menu"
            aria-expanded={menuOpen}
            onClick={() => setMenuOpen(!menuOpen)}
          >
            <span className="spa-header__bar" />
            <span className="spa-header__bar" />
            <span className="spa-header__bar" />
          </button>
        </div>
      </div>

      {menuOpen && (
        <div className="spa-header__mobile-menu" role="dialog" aria-modal="true">
          <a href="#hero" className="spa-header__mobile-link" onClick={() => setMenuOpen(false)}>Home</a>
          <a href="#fleet" className="spa-header__mobile-link" onClick={() => setMenuOpen(false)}>Fleet Specifications</a>
          <a href="#footer" className="spa-header__mobile-link" onClick={() => setMenuOpen(false)}>Contact</a>
          <a href="mailto:charter@sovereignaviation.com" className="spa-header__mobile-cta" onClick={() => setMenuOpen(false)}>Book Private Flight</a>
        </div>
      )}
    </header>
  );
}
