  id: string;
  category: string;
  title: string;
  desc: string;
  badge: string;
}

interface Review {
  id: string;
  quote: string;
  author: string;
  role: string;
  rating: number;
}

const FEATURES: Feature[] = [{'title': 'Real-Time Multi-Cursor Docs', 'tag': 'CRDT Collab', 'desc': 'Collaborative markdown editing with zero lag, rich code blocks, and embedded interactive tables.'}, {'title': 'Keyboard-First Command Palette', 'tag': 'Command + K', 'desc': 'Navigate issues, assign tickets, and create documents without your fingers leaving the home row.'}, {'title': 'Two-Way GitHub & GitLab Sync', 'tag': 'Branch Auto-Close', 'desc': 'Issues update automatically when PRs are opened, reviewed, merged, or reverted.'}, {'title': 'Automated Async Standups', 'tag': 'Slack & Discord', 'desc': 'Gather daily engineering updates automatically without forcing developers into 30-minute Zoom meetings.'}];
const REVIEWS: Review[] = [{'id': '1', 'quote': 'Deploying Harmony Workspace transformed our delivery velocity. The real-time multi-cursor docs capabilities delivered immediate impact.', 'author': 'Alex Chen', 'role': 'Head of Engineering, Harmony Workspace', 'rating': 5}, {'id': '2', 'quote': 'With Harmony Workspace, we automated asynchronous sprint planning, collaborative docs & engineering roadmaps while accelerating our product delivery.', 'author': 'Samantha Wei', 'role': 'VP of Technology at Harmony Workspace Group', 'rating': 5}, {'id': '3', 'quote': 'Our developers love using Harmony Workspace. The keyboard-first command palette workflow is best in class.', 'author': 'Marcus Thorne', 'role': 'Principal Architect', 'rating': 5}];
const CATEGORIES: { id: string; label: string }[] = [{'id': 'all', 'label': 'All Capabilities'}, {'id': 'core', 'label': 'Core Engine'}, {'id': 'security', 'label': 'Security & Auth'}, {'id': 'scale', 'label': 'Scale & Telemetry'}];

export function WorkspaceModules() {
  const [activeTab, setActiveTab] = useState<string>('all');
  const [activeSlide, setActiveSlide] = useState<number>(0);

  const filteredFeatures = activeTab === 'all'
    ? FEATURES
    : FEATURES.filter((f) => f.category === activeTab);

  const prevSlide = () => {
    setActiveSlide((prev) => (prev - 1 + REVIEWS.length) % REVIEWS.length);
  };

  const nextSlide = () => {
    setActiveSlide((prev) => (prev + 1) % REVIEWS.length);
  };

  const currentReview = REVIEWS[activeSlide];

  return (
    <section className="hw-tabs" id="workspacemodules" aria-labelledby="hw-tabs-title">
      <div className="hw-tabs__inner">
        {/* 1. Header & Tab Navigation */}
        <div className="hw-tabs__header">
          <p className="hw-tabs__eyebrow">SAAS SOLUTIONS</p>
          <h2 id="hw-tabs-title" className="hw-tabs__title">
            Workspace Modules
          </h2>
          <p className="hw-tabs__subtitle">
            Explore verified solutions and live client outcomes from Harmony Workspace.
          </p>

          <div className="hw-tabs__nav" role="tablist" aria-label="Feature categories">
            {CATEGORIES.map((cat) => (
              <button
                key={cat.id}
                type="button"
                role="tab"
                aria-selected={activeTab === cat.id}
                className={`hw-tabs__tab${activeTab === cat.id ? ' is-active' : ''}`}
                onClick={() => setActiveTab(cat.id)}
              >
                {cat.label}
              </button>
            ))}
          </div>
        </div>

        {/* 2. Filtered Cards Grid */}
        <div className="hw-tabs__grid">
          {filteredFeatures.map((item) => (
            <div key={item.id} className="hw-tabs__card">
              <div className="hw-tabs__card-top">
                <span className="hw-tabs__badge">{item.badge}</span>
                <span className="hw-tabs__category">{item.category}</span>
              </div>
              <h3 className="hw-tabs__card-title">{item.title}</h3>
              <p className="hw-tabs__card-desc">{item.desc}</p>
            </div>
          ))}
        </div>

        {/* 3. Carousel Component — Testimonials & Proof */}
        <div className="hw-tabs__carousel" aria-label="Customer Testimonials">
          <div className="hw-tabs__carousel-box">
            <div className="hw-tabs__stars" aria-label="5 stars rating">
              {'★'.repeat(currentReview.rating)}
            </div>

            <blockquote className="hw-tabs__quote">
              &ldquo;{currentReview.quote}&rdquo;
            </blockquote>

            <div className="hw-tabs__author">
              <div className="hw-tabs__author-avatar" aria-hidden="true">
                {currentReview.author.split(' ').map((n) => n[0]).join('')}
              </div>
              <div>
                <h4 className="hw-tabs__author-name">{currentReview.author}</h4>
                <span className="hw-tabs__author-role">{currentReview.role}</span>
              </div>
            </div>

            <div className="hw-tabs__carousel-controls">
              <button
                type="button"
                onClick={prevSlide}
                className="hw-tabs__carousel-btn"
                aria-label="Previous testimonial"
              >
                &larr;
              </button>
              <span className="hw-tabs__carousel-counter">
                0{activeSlide + 1} / 0{REVIEWS.length}
              </span>
              <button
                type="button"
                onClick={nextSlide}
                className="hw-tabs__carousel-btn"
                aria-label="Next testimonial"
              >
                &rarr;
              </button>
            </div>
          </div>
        </div>
      </div>
    </section>
  );
}
</file>
