import React, { useState, useEffect } from 'react';
import './Header.css';

export function Header() {
  const [scrolled, setScrolled] = useState(false);
  const [menuOpen, setMenuOpen] = useState(false);

  useEffect(() => {
    const onScroll = () => setScrolled(window.scrollY > 15);
    window.addEventListener('scroll', onScroll, { passive: true });
    return () => window.removeEventListener('scroll', onScroll);
  }, []);

  return (
    <header className={`sh-header${scrolled ? ' sh-header--scrolled' : ''}`} role="banner">
      <div className="sh-header__inner">
        <a href="#" className="sh-header__logo" aria-label="Shield Harbor Marine Insurance Home">
          Shield Harbor Marine Insurance
        </a>

        <nav className="sh-header__nav" aria-label="Main Navigation">
          <a href="#hero" className="sh-header__link">Home</a>
          <a href="#policies" className="sh-header__link">Coverage Policies</a>
          <a href="#footer" className="sh-header__link">Contact</a>
        </nav>

        <div className="sh-header__actions">
          <a href="mailto:underwriting@shieldharbormarine.com" className="sh-header__cta">
            Request Marine Quote
          </a>
          <button
            type="button"
            className="sh-header__toggle"
            aria-label="Toggle navigation menu"
            aria-expanded={menuOpen}
            onClick={() => setMenuOpen(!menuOpen)}
          >
            <span className="sh-header__bar" />
            <span className="sh-header__bar" />
            <span className="sh-header__bar" />
          </button>
        </div>
      </div>

      {menuOpen && (
        <div className="sh-header__mobile-menu">
          <a href="#hero" onClick={() => setMenuOpen(false)}>Home</a>
          <a href="#policies" onClick={() => setMenuOpen(false)}>Coverage Policies</a>
          <a href="#footer" onClick={() => setMenuOpen(false)}>Contact</a>
        </div>
      )}
    </header>
  );
}

