import React, { useState, useEffect } from 'react';
import './Header.css';

export function Header() {
  const [scrolled, setScrolled] = useState(false);
  const [menuOpen, setMenuOpen] = useState(false);

  useEffect(() => {
    const onScroll = () => setScrolled(window.scrollY > 15);
    window.addEventListener('scroll', onScroll, { passive: true });
    return () => window.removeEventListener('scroll', onScroll);
  }, []);

  return (
    <header className={`rsc-header${scrolled ? ' rsc-header--scrolled' : ''}`} role="banner">
      <div className="rsc-header__inner">
        <a href="#" className="rsc-header__logo" aria-label="Rebel Strategy Collective Home">
          Rebel Strategy Collective
        </a>

        <nav className="rsc-header__nav" aria-label="Main Navigation">
          <a href="#hero" className="rsc-header__link">Home</a>
          <a href="#campaigns" className="rsc-header__link">Past Campaigns</a>
          <a href="#footer" className="rsc-header__link">Contact</a>
        </nav>

        <div className="rsc-header__actions">
          <a href="mailto:riot@rebelstrategy.co" className="rsc-header__cta">
            Start a Riot
          </a>
          <button
            type="button"
            className="rsc-header__toggle"
            aria-label="Toggle navigation menu"
            aria-expanded={menuOpen}
            onClick={() => setMenuOpen(!menuOpen)}
          >
            <span className="rsc-header__bar" />
            <span className="rsc-header__bar" />
            <span className="rsc-header__bar" />
          </button>
        </div>
      </div>

      {menuOpen && (
        <div className="rsc-header__mobile-menu" role="dialog" aria-modal="true">
          <a href="#hero" className="rsc-header__mobile-link" onClick={() => setMenuOpen(false)}>Home</a>
          <a href="#campaigns" className="rsc-header__mobile-link" onClick={() => setMenuOpen(false)}>Past Campaigns</a>
          <a href="#footer" className="rsc-header__mobile-link" onClick={() => setMenuOpen(false)}>Contact</a>
          <a href="mailto:riot@rebelstrategy.co" className="rsc-header__mobile-cta" onClick={() => setMenuOpen(false)}>Start a Riot</a>
        </div>
      )}
    </header>
  );
}
