import React, { useState } from 'react';
import './Monitoring.css';

interface Feature {
  id: string;
  category: string;
  title: string;
  desc: string;
  badge: string;
}

interface Review {
  id: string;
  quote: string;
  author: string;
  role: string;
  rating: number;
}

const FEATURES: Feature[] = [{'title': '1-Second Resolution Probing', 'tag': '65 Global Cities', 'desc': 'Detect micro-outages and regional DNS routing failures within 3 seconds of occurrence.'}, {'title': 'Multi-Step API Transaction Checks', 'tag': 'Synthetic User', 'desc': 'Simulate complete user journeys (login, add to cart, checkout) every 5 minutes.'}, {'title': 'SSL Certificate Expiry Alerts', 'tag': '30-Day Warning', 'desc': 'Receive automated warnings 30, 14, and 3 days before HTTPS certificates expire.'}, {'title': 'Public Incident Status Pages', 'tag': 'Custom CNAME', 'desc': 'Host independent status pages on high-availability infrastructure that stays up during outages.'}];
const REVIEWS: Review[] = [{'id': '1', 'quote': 'Deploying PingPulse Monitoring transformed our delivery velocity. The 1-second resolution probing capabilities delivered immediate impact.', 'author': 'Alex Chen', 'role': 'Head of Engineering, PingPulse Monitoring', 'rating': 5}, {'id': '2', 'quote': 'With PingPulse Monitoring, we automated global multi-region uptime monitoring with 1-second check intervals while accelerating our product delivery.', 'author': 'Samantha Wei', 'role': 'VP of Technology at PingPulse Monitoring Group', 'rating': 5}, {'id': '3', 'quote': 'Our developers love using PingPulse Monitoring. The multi-step api transaction checks workflow is best in class.', 'author': 'Marcus Thorne', 'role': 'Principal Architect', 'rating': 5}];
const CATEGORIES: { id: string; label: string }[] = [{'id': 'all', 'label': 'All Capabilities'}, {'id': 'core', 'label': 'Core Engine'}, {'id': 'security', 'label': 'Security & Auth'}, {'id': 'scale', 'label': 'Scale & Telemetry'}];

export function Monitoring() {
  const [activeTab, setActiveTab] = useState<string>('all');
  const [activeSlide, setActiveSlide] = useState<number>(0);

  const filteredFeatures = activeTab === 'all'
    ? FEATURES
    : FEATURES.filter((f) => f.category === activeTab);

  const prevSlide = () => {
    setActiveSlide((prev) => (prev - 1 + REVIEWS.length) % REVIEWS.length);
  };

  const nextSlide = () => {
    setActiveSlide((prev) => (prev + 1) % REVIEWS.length);
  };

  const currentReview = REVIEWS[activeSlide];

  return (
    <section className="ppm-tabs" id="monitoring" aria-labelledby="ppm-tabs-title">
      <div className="ppm-tabs__inner">
        {/* 1. Header & Tab Navigation */}
        <div className="ppm-tabs__header">
          <p className="ppm-tabs__eyebrow">DEVOPS SOLUTIONS</p>
          <h2 id="ppm-tabs-title" className="ppm-tabs__title">
            Monitoring Tools
          </h2>
          <p className="ppm-tabs__subtitle">
            Explore verified solutions and live client outcomes from PingPulse Monitoring.
          </p>

          <div className="ppm-tabs__nav" role="tablist" aria-label="Feature categories">
            {CATEGORIES.map((cat) => (
              <button
                key={cat.id}
                type="button"
                role="tab"
                aria-selected={activeTab === cat.id}
                className={`ppm-tabs__tab${activeTab === cat.id ? ' is-active' : ''}`}
                onClick={() => setActiveTab(cat.id)}
              >
                {cat.label}
              </button>
            ))}
          </div>
        </div>

        {/* 2. Filtered Cards Grid */}
        <div className="ppm-tabs__grid">
          {filteredFeatures.map((item) => (
            <div key={item.id} className="ppm-tabs__card">
              <div className="ppm-tabs__card-top">
                <span className="ppm-tabs__badge">{item.badge}</span>
                <span className="ppm-tabs__category">{item.category}</span>
              </div>
              <h3 className="ppm-tabs__card-title">{item.title}</h3>
              <p className="ppm-tabs__card-desc">{item.desc}</p>
            </div>
          ))}
        </div>

        {/* 3. Carousel Component — Testimonials & Proof */}
        <div className="ppm-tabs__carousel" aria-label="Customer Testimonials">
          <div className="ppm-tabs__carousel-box">
            <div className="ppm-tabs__stars" aria-label="5 stars rating">
              {'★'.repeat(currentReview.rating)}
            </div>

            <blockquote className="ppm-tabs__quote">
              &ldquo;{currentReview.quote}&rdquo;
            </blockquote>

            <div className="ppm-tabs__author">
              <div className="ppm-tabs__author-avatar" aria-hidden="true">
                {currentReview.author.split(' ').map((n) => n[0]).join('')}
              </div>
              <div>
                <h4 className="ppm-tabs__author-name">{currentReview.author}</h4>
                <span className="ppm-tabs__author-role">{currentReview.role}</span>
              </div>
            </div>

            <div className="ppm-tabs__carousel-controls">
              <button
                type="button"
                onClick={prevSlide}
                className="ppm-tabs__carousel-btn"
                aria-label="Previous testimonial"
              >
                &larr;
              </button>
              <span className="ppm-tabs__carousel-counter">
                0{activeSlide + 1} / 0{REVIEWS.length}
              </span>
              <button
                type="button"
                onClick={nextSlide}
                className="ppm-tabs__carousel-btn"
                aria-label="Next testimonial"
              >
                &rarr;
              </button>
            </div>
          </div>
        </div>
      </div>
    </section>
  );
}
