import React, { useState, useEffect } from 'react';
import './Header.css';

export function Header() {
  const [scrolled, setScrolled] = useState(false);
  const [menuOpen, setMenuOpen] = useState(false);

  useEffect(() => {
    const onScroll = () => setScrolled(window.scrollY > 15);
    window.addEventListener('scroll', onScroll, { passive: true });
    return () => window.removeEventListener('scroll', onScroll);
  }, []);

  return (
    <header className={`as-header${scrolled ? ' as-header--scrolled' : ''}`} role="banner">
      <div className="as-header__inner">
        <a href="#" className="as-header__logo" aria-label="Apex Sonic Scoring Home">
          Apex Sonic Scoring
        </a>

        <nav className="as-header__nav" aria-label="Main Navigation">
          <a href="#hero" className="as-header__link">Home</a>
          <a href="#works" className="as-header__link">Scoring Works</a>
          <a href="#footer" className="as-header__link">Contact</a>
        </nav>

        <div className="as-header__actions">
          <a href="mailto:studio@apexsonicscoring.com" className="as-header__cta">
            Listen to Showreel
          </a>
          <button
            type="button"
            className="as-header__toggle"
            aria-label="Toggle navigation menu"
            aria-expanded={menuOpen}
            onClick={() => setMenuOpen(!menuOpen)}
          >
            <span className="as-header__bar" />
            <span className="as-header__bar" />
            <span className="as-header__bar" />
          </button>
        </div>
      </div>

      {menuOpen && (
        <div className="as-header__mobile-menu">
          <a href="#hero" onClick={() => setMenuOpen(false)}>Home</a>
          <a href="#works" onClick={() => setMenuOpen(false)}>Scoring Works</a>
          <a href="#footer" onClick={() => setMenuOpen(false)}>Contact</a>
        </div>
      )}
    </header>
  );
}

