import React from 'react';
import './TelemetryEngines.css';

interface Milestone {
  step: string;
  title: string;
  tag: string;
  desc: string;
}

const MILESTONES: Milestone[] = [
  {
    "step": "Phase 01",
    "title": "Kernel-Level TCP Tracing",
    "tag": "Zero Overhead",
    "desc": "Monitor SYN packet drops, socket retransmissions, and round-trip jitter directly inside the Linux socket layer."
  },
  {
    "step": "Phase 02",
    "title": "Distributed Trace Graph",
    "tag": "Automatic",
    "desc": "Autonomous trace reconstruction across microservices via kernel context propagation with zero application bytecode instrumentation."
  },
  {
    "step": "Phase 03",
    "title": "Security Anomaly Detection",
    "tag": "Real-Time",
    "desc": "Trap unauthorized execve syscalls, root privilege escalations, and suspicious outbound DNS queries in milliseconds."
  },
  {
    "step": "Phase 04",
    "title": "OTel Native Exporter",
    "tag": "OpenTelemetry",
    "desc": "Stream high-fidelity kernel metrics into existing Prometheus, Datadog, and Grafana pipelines seamlessly."
  }
];

export function TelemetryEngines() {
  const trackRef = React.useRef<HTMLDivElement>(null);

  React.useEffect(() => {
    const observer = new IntersectionObserver(
      (entries) => {
        entries.forEach((entry) => {
          if (entry.isIntersecting) {
            entry.target.classList.add('is-revealed');
          }
        });
      },
      { threshold: 0.2 }
    );

    const nodes = trackRef.current?.querySelectorAll('.kt-timeline__node');
    nodes?.forEach((node) => observer.observe(node));

    return () => observer.disconnect();
  }, []);

  return (
    <section className="kt-timeline" id="engines" aria-labelledby="kt-timeline-title">
      <div className="kt-timeline__inner">
        <div className="kt-timeline__header">
          <p className="kt-timeline__eyebrow">Sequential Roadmap</p>
          <h2 id="kt-timeline-title" className="kt-timeline__title">
            Telemetry Engines
          </h2>
          <p className="kt-timeline__desc">
            Kernel-level eBPF packet tracing, zero-overhead Kubernetes container telemetry, and distributed latency profiling.
          </p>
        </div>

        <div ref={trackRef} className="kt-timeline__track">
          <div className="kt-timeline__spine" aria-hidden="true" />
          {MILESTONES.map((m) => (
            <article key={m.title} className="kt-timeline__node">
              <div className="kt-timeline__marker" aria-hidden="true">
                <span className="kt-timeline__dot" />
              </div>
              <div className="kt-timeline__card">
                <div className="kt-timeline__card-top">
                  <span className="kt-timeline__step">{m.step}</span>
                  <span className="kt-timeline__tag">{m.tag}</span>
                </div>
                <h3 className="kt-timeline__card-title">{m.title}</h3>
                <p className="kt-timeline__card-desc">{m.desc}</p>
              </div>
            </article>
          ))}
        </div>
      </div>
    </section>
  );
}

